function validate([s1, s2, s3]) {
  for (const s of [s1, s2, s3]) {
    if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 'Each string has 1 to 100 characters.';
    if (!/^[a-z]+$/.test(s)) return 'Strings use only lowercase English letters.';
  }
  return null;
}

