function findMinimumOperations(s1, s2, s3) {
  const shortest = Math.min(s1.length, s2.length, s3.length);
  let common = 0;
  while (common < shortest && s1[common] === s2[common] && s2[common] === s3[common]) {
    common++;
  }
  if (common === 0) {
    return -1;
  }
  return s1.length + s2.length + s3.length - 3 * common;
}

