function findMinimumOperations(s1, s2, s3) {
  let best = -1;
  for (let keep = 1; keep <= Math.min(s1.length, s2.length, s3.length); keep++) {
    const a = s1.slice(0, keep), b = s2.slice(0, keep), c = s3.slice(0, keep);
    if (a !== b || b !== c) continue;
    const cost = (s1.length - keep) + (s2.length - keep) + (s3.length - keep);
    if (best === -1 || cost < best) best = cost;
  }
  return best;
}

