function generate(rand, size) {
  const letters = rand() < 0.5 ? 'ab' : 'abcz';
  const word = n => Array.from({ length: n }, () => letters[Math.floor(rand() * letters.length)]).join('');
  const max = size === 'large' ? 100 : 5;
  const shared = word(Math.floor(rand() * (max + 1)));
  const make = () => {
    const keep = Math.floor(rand() * (shared.length + 1));
    const base = shared.slice(0, keep) + word(Math.floor(rand() * (max - keep + 1)));
    return base.length ? base : word(1);
  };
  return [make(), make(), make()];
}
